def _to_rdflib(self) -> Literal | URIRef:
    from .entity import Entity
    from .iri import IRI
    from .quantity import Quantity
    from .string import String
    from .text import Text
    from .time import Time
    if isinstance(self, Entity):
        return URIRef(self.iri.content)
    elif isinstance(self, IRI):
        return URIRef(self.content)
    elif isinstance(self, Quantity):
        return Literal(str(self.amount), datatype=NS.XSD.decimal)
    elif isinstance(self, Time):
        return Literal(self.time.isoformat(), datatype=NS.XSD.dateTime)
    elif isinstance(self, Text):
        return Literal(self.content, self.language)
    elif isinstance(self, String):
        return Literal(self.content)
    else:
        raise self._should_not_get_here()

def _URI(self, val) :
	"""Returns a URI for a 'pure' URI (ie, not a CURIE). The method resolves possible relative URI-s. It also
	checks whether the URI uses an unusual URI scheme (and issues a warning); this may be the result of an
	uninterpreted CURIE...
	@param val: attribute value to be interpreted
	@type val: string
	@return: an RDFLib URIRef instance
	"""
	def create_URIRef(uri, check = True) :
		"""
		Mini helping function: it checks whether a uri is using a usual scheme before a URIRef is created. In case
		there is something unusual, a warning is generated (though the URIRef is created nevertheless)
		@param uri: (absolute) URI string
		@return: an RDFLib URIRef instance
		"""
		from .	import uri_schemes
		val = uri.strip()
		if check and urlsplit(val)[0] not in uri_schemes :
			self.options.add_warning(err_URI_scheme % val.strip(), node=self.node.nodeName)
		return URIRef(val)

	def join(base, v, check = True) :
		"""
		Mini helping function: it makes a urljoin for the paths. Based on the python library, but
		that one has a bug: in some cases it
		swallows the '#' or '?' character at the end. This is clearly a problem with
		Semantic Web URI-s, so this is checked, too
		@param base: base URI string
		@param v: local part
		@param check: whether the URI should be checked against the list of 'existing' URI schemes
		@return: an RDFLib URIRef instance
		"""
		# UGLY!!! There is a bug for a corner case in python version <= 2.5.X
		if len(v) > 0 and v[0] == '?' and (py_v_major < 3 and py_v_minor <= 5) :
			return create_URIRef(base+v, check)
		####

		joined = urljoin(base, v)
		try :
			if v[-1] != joined[-1] and (v[-1] == "#" or v[-1] == "?") :
				return create_URIRef(joined + v[-1], check)
			else :
				return create_URIRef(joined, check)
		except :
			return create_URIRef(joined, check)

	if val == "" :
		# The fragment ID must be removed...
		return URIRef(self.base)

	# fall back on good old traditional URI-s.
	# To be on the safe side, let us use the Python libraries
	if self.parsedBase[0] == "" :
		# base is, in fact, a local file name
		# The following call is just to be sure that some pathological cases when
		# the ':' _does_ appear in the URI but not in a scheme position is taken
		# care of properly...

		key = urlsplit(val)[0]
		if key == "" :
			# relative URI, to be combined with local file name:
			return join(self.base, val, check = False)
		else :
			return create_URIRef(val)
	else :
		# Trust the python library...
		# Well, not quite:-) there is what is, in my view, a bug in the urljoin; in some cases it
		# swallows the '#' or '?' character at the end. This is clearly a problem with
		# Semantic Web URI-s			
		return join(self.base, val)

def _CURIEorURI(self, val) :
	"""Returns a URI for a (safe or not safe) CURIE. In case it is a safe CURIE but the CURIE itself
	is not defined, an error message is issued. Otherwise, if it is not a CURIE, it is taken to be a URI
	@param val: attribute value to be interpreted
	@type val: string
	@return: an RDFLib URIRef instance or None
	"""
	if val == "" :
		return URIRef(self.base)

	safe_curie = False
	if val[0] == '[' :
		# If a safe CURIE is asked for, a pure URI is not acceptable.
		# Is checked below, and that is why the safe_curie flag is necessary
		if val[-1] != ']' :
			# that is certainly forbidden: an incomplete safe CURIE
			self.options.add_warning(err_illegal_safe_CURIE % val, UnresolvablePrefix, node=self.node.nodeName)
			return None
		else :
			val = val[1:-1]
			safe_curie = True
	# There is a branch here depending on whether we are in 1.1 or 1.0 mode
	if self.rdfa_version >= "1.1" :
		retval = self.term_or_curie.CURIE_to_URI(val)
		if retval == None :
			# the value could not be interpreted as a CURIE, ie, it did not produce any valid URI.
			# The rule says that then the whole value should be considered as a URI
			# except if it was part of a safe CURIE. In that case it should be ignored...
			if safe_curie :
				self.options.add_warning(err_no_CURIE_in_safe_CURIE % val, UnresolvablePrefix, node=self.node.nodeName)
				return None
			else :
				return self._URI(val)
		else :
			# there is an unlikely case where the retval is actually a URIRef with a relative URI. Better filter that one out
			if isinstance(retval, BNode) == False and urlsplit(str(retval))[0] == "" :
				# yep, there is something wrong, a new URIRef has to be created:
				return URIRef(self.base+str(retval))
			else :
				return retval
	else :
		# in 1.0 mode a CURIE can be considered only in case of a safe CURIE
		if safe_curie :
			return self.term_or_curie.CURIE_to_URI(val)
		else :
			return self._URI(val)

def absolutize(self, iri):

    """
    Apply BASE / PREFIXes to URIs
    (and to datatypes in Literals)

    TODO: Move resolving URIs to pre-processing
    """

    if isinstance(iri, CompValue):
        if iri.name == 'pname':
            return self.resolvePName(iri.prefix, iri.localname)
        if iri.name == 'literal':
            return Literal(
                iri.string, lang=iri.lang,
                datatype=self.absolutize(iri.datatype))
    elif isinstance(iri, URIRef) and not ':' in iri:
        return URIRef(iri, base=self.base)

    return iri

def validate_fdo_record(record: FdoRecord, profile_np: FdoNanopub = None) -> ValidationResult:
    try:
        shape_graph = None

        if profile_np is not None:
            shape_graph = profile_np.assertion
        else:
            profile_uri = record.get_profile()
            if not profile_uri:
                return ValidationResult(False, ["FDO profile URI not found in record."], [])

            if str(profile_uri).startswith("https://doi.org/"):
                # DTR-style profile: follow DOI to get DTR JSON, then fetch schema.url
                resp = requests.get(
                    str(profile_uri),
                    headers={"Accept": "application/json"},
                    timeout=DEFAULT_HTTP_TIMEOUT,
                )
                if resp.status_code != 200:
                    return ValidationResult(False, [f"Could not fetch DTR profile for {profile_uri}"], [])
                dtr_json = resp.json()
                schema_url = dtr_json.get("schema", {}).get("url")
                if not schema_url:
                    return ValidationResult(False, [f"No schema URL found in DTR profile for {profile_uri}"], [])
                schema_resp = requests.get(schema_url, timeout=DEFAULT_HTTP_TIMEOUT)
                if schema_resp.status_code != 200:
                    return ValidationResult(False, [f"Could not fetch JSON schema from {schema_url}"], [])
                schema_json = schema_resp.json()
                shape_graph = convert_jsonschema_to_shacl(schema_json)

            elif looks_like_handle(profile_uri) or str(profile_uri).startswith("https://hdl.handle.net/"):
                api_url = _profile_landing_page_uri_to_api_url(str(profile_uri))
                resp = requests.get(api_url, timeout=DEFAULT_HTTP_TIMEOUT)
                if resp.status_code != 200:
                    return ValidationResult(False, [f"Could not fetch handle metadata for {api_url}"], [])
                metadata = resp.json()

                schema_entry = next(
                    (v for v in metadata.get("values", []) if v["type"].endswith("JsonSchema")),
                    None
                )
                if not schema_entry:
                    return ValidationResult(False, ["JSON Schema entry not found in FDO profile."], [])

                schema_str = schema_entry["data"]["value"]
                schema_json = json.loads(schema_str)
                shape_graph = convert_jsonschema_to_shacl(schema_json)

            else:
                profile_np = resolve_in_nanopub_network(profile_uri)
                if not profile_np:
                    return ValidationResult(False, [f"Could not resolve profile nanopub for {profile_uri}"], [])
                shape_graph = fix_numeric_shacl_constraints(profile_np.assertion)

        if shape_graph is None:
            return ValidationResult(False, ["SHACL shape graph could not be created."], [])

        graph = record.get_graph()
        _prev_normalize = rdflib.NORMALIZE_LITERALS
        try:
            conforms, results_graph, results_text = _pyshacl_validate(
                graph,
                shacl_graph=shape_graph,
                inference="rdfs",
                abort_on_first=False,
                meta_shacl=False,
                advanced=True,
                debug=False
            )
        finally:
            rdflib.NORMALIZE_LITERALS = _prev_normalize

        errors = [str(o) for s, p, o in results_graph.triples((None, SH.resultMessage, None))]
        return ValidationResult(conforms, errors, [])

    except Exception as e:
        return ValidationResult(False, [f"Validation error: {str(e)}"], [])

import re
import sys
from abc import ABC
from typing import Any, ClassVar, Final, Literal, TypeVar, cast, get_args

from pydantic import BaseModel, ConfigDict, Field, field_validator, model_validator
from rdflib import Literal as RDFLiteral
from rdflib import URIRef

from cognite.neat._v0.core._data_model._constants import EntityTypes
from cognite.neat._v0.core._data_model.models.data_types import _XSD_TYPES, DataType
from cognite.neat._v0.core._data_model.models.entities._constants import _PARSE
from cognite.neat._v0.core._data_model.models.entities._single_value import ConceptEntity, ConceptualEntity
from cognite.neat._v0.core._issues.errors._general import NeatValueError
from cognite.neat._v0.core._utils.rdf_ import remove_namespace_from_uri

if sys.version_info <= (3, 11):
    from typing_extensions import Self
else:
    from typing import Self


ValueConstraints = Literal["allValuesFrom", "someValuesFrom", "hasValue"]
CardinalityConstraints = Literal["minCardinality", "maxCardinality", "cardinality", "qualifiedCardinality"]


# Constants for regex patterns - more maintainable
PROPERTY_PATTERN: Final[str] = r"[a-zA-Z0-9._~?@!$&'*+,;=%-]+"
VALUE_PATTERN: Final[str] = r".+"
CARDINALITY_VALUE_PATTERN: Final[str] = r"\d+"
ON_PATTERN: Final[str] = r"[^(]*"

VALUE_CONSTRAINT_REGEX = re.compile(
    rf"^{EntityTypes.value_constraint}:(?P<property>{PROPERTY_PATTERN})\((?P<constraint>{'|'.join(get_args(ValueConstraints))}),(?P<value>{VALUE_PATTERN})\)$"
)

CARDINALITY_CONSTRAINT_REGEX = re.compile(
    rf"^{EntityTypes.cardinality_constraint}:(?P<property>{PROPERTY_PATTERN})\((?P<constraint>{'|'.join(get_args(CardinalityConstraints))}),(?P<value>{CARDINALITY_VALUE_PATTERN})(?:,(?P<on>{ON_PATTERN}))?\)$"
)


class NamedIndividualEntity(ConceptualEntity):
    type_: ClassVar[EntityTypes] = EntityTypes.named_individual

    @model_validator(mode="after")
    def reset_prefix(self) -> Self:
        self.prefix = "ni"
        return self


class ConceptPropertyRestriction(ABC, BaseModel):
    model_config: ClassVar[ConfigDict] = ConfigDict(
        str_strip_whitespace=True,
        arbitrary_types_allowed=True,
        strict=False,
        extra="ignore",
    )
    type_: ClassVar[EntityTypes] = EntityTypes.concept_restriction
    property_: str

    @classmethod
    def load(cls: "type[T_ConceptPropertyRestriction]", data: Any, **defaults: Any) -> "T_ConceptPropertyRestriction":
        if isinstance(data, cls):
            return data
        elif not isinstance(data, str):
            raise ValueError(f"Cannot load {cls.__name__} from {data}")

        return cls.model_validate({_PARSE: data, "defaults": defaults})

    @model_validator(mode="before")
    def _load(cls, data: Any) -> dict:
        defaults = {}
        if isinstance(data, dict) and _PARSE in data:
            defaults = data.get("defaults", {})
            data = data[_PARSE]
        if isinstance(data, dict):
            data.update(defaults)
            return data

        if not isinstance(data, str):
            raise ValueError(f"Cannot load {cls.__name__} from {data}")

        return cls._parse(data, defaults)

    @classmethod
    def _parse(cls, data: str, defaults: dict) -> dict:
        raise NotImplementedError(f"{cls.__name__} must implement _parse method")

    def dump(self) -> str:
        return self.__str__()

    def as_tuple(self) -> tuple[str, ...]:
        # We haver overwritten the serialization to str, so we need to do it manually
        extra: tuple[str, ...] = tuple(
            [
                str(v or "")
                for field_name in self.model_fields.keys()
                if (v := getattr(self, field_name)) and field_name not in {"property_"}
            ]
        )

        return self.property_, *extra

    def __lt__(self, other: object) -> bool:
        if not isinstance(other, ConceptPropertyRestriction):
            return NotImplemented
        return self.as_tuple() < other.as_tuple()

    def __eq__(self, other: object) -> bool:
        if not isinstance(other, ConceptPropertyRestriction):
            return NotImplemented
        return self.as_tuple() == other.as_tuple()

    def __hash__(self) -> int:
        return hash(str(self))


T_ConceptPropertyRestriction = TypeVar("T_ConceptPropertyRestriction", bound="ConceptPropertyRestriction")


class ConceptPropertyValueConstraint(ConceptPropertyRestriction):
    type_: ClassVar[EntityTypes] = EntityTypes.value_constraint
    constraint: ValueConstraints
    value: RDFLiteral | ConceptEntity | NamedIndividualEntity

    @field_validator("value")
    def validate_value(cls, value: Any) -> Any:
        if isinstance(value, RDFLiteral) and value.datatype is None:
            raise NeatValueError("RDFLiteral must have a datatype set, which must be one of the XSD types.")
        return value

    def __str__(self) -> str:
        value_str = (
            f"{self.value.value}^^{remove_namespace_from_uri(cast(URIRef, self.value.datatype))}"
            if isinstance(self.value, RDFLiteral)
            else str(self.value)
        )
        return f"{self.type_}:{self.property_}({self.constraint},{value_str})"

    @classmethod
    def _parse(cls, data: str, defaults: dict) -> dict:
        if not (result := VALUE_CONSTRAINT_REGEX.match(data)):
            raise NeatValueError(f"Invalid value constraint format: {data}")

        property_ = result.group("property")
        constraint = result.group("constraint")
        raw_value = result.group("value")

        value: NamedIndividualEntity | RDFLiteral | ConceptEntity
        # scenario 1: NamedIndividual as value restriction
        if raw_value.startswith("ni:"):
            value = NamedIndividualEntity.load(raw_value)
        # scenario 2: Datatype as value restriction
        elif "^^" in raw_value:
            if len(value_components := raw_value.split("^^")) == 2 and value_components[1] in _XSD_TYPES:
                value = RDFLiteral(value_components[0], datatype=DataType.load(value_components[1]).as_xml_uri_ref())
            else:
                raise NeatValueError(f"Invalid value format for datatype: {raw_value}")

        # scenario 3: ConceptEntity as value restriction
        else:
            value = ConceptEntity.load(raw_value, **defaults)

        return dict(property_=property_, constraint=constraint, value=value)


class ConceptPropertyCardinalityConstraint(ConceptPropertyRestriction):
    type_: ClassVar[EntityTypes] = EntityTypes.cardinality_constraint
    constraint: CardinalityConstraints
    value: int = Field(ge=0)
    on: DataType | ConceptEntity | None = None

    def __str__(self) -> str:
        on_str = f",{self.on}" if self.on else ""
        return f"{self.type_}:{self.property_}({self.constraint},{self.value}{on_str})"

    @classmethod
    def _parse(cls, data: str, defaults: dict) -> dict:
        if not (result := CARDINALITY_CONSTRAINT_REGEX.match(data)):
            raise NeatValueError(f"Invalid cardinality constraint format: {data}")

        property_ = result.group("property")
        constraint = result.group("constraint")
        value = result.group("value")
        on = result.group("on")
        if on:
            if on in _XSD_TYPES:
                on = DataType.load(on)
            else:
                on = cast(ConceptEntity, ConceptEntity.load(on, **defaults))

        return dict(property_=property_, constraint=constraint, value=value, on=on)


def parse_restriction(data: str, **defaults: Any) -> ConceptPropertyRestriction:
    """Parse a string to create either a value or cardinality restriction.

    Args:
        data: String representation of the restriction
        **defaults: Default values to use when parsing

    Returns:
        Either a ConceptPropertyValueConstraint or ConceptPropertyCardinalityConstraint

    Raises:
        NeatValueError: If the string cannot be parsed as either restriction type
    """
    # Check for value constraint pattern first (more specific)
    if VALUE_CONSTRAINT_REGEX.match(data):
        try:
            return ConceptPropertyValueConstraint.load(data, **defaults)
        except Exception as e:
            raise NeatValueError(f"Failed to parse value constraint: {data}") from e

    # Check for cardinality constraint pattern
    if CARDINALITY_CONSTRAINT_REGEX.match(data):
        try:
            return ConceptPropertyCardinalityConstraint.load(data, **defaults)
        except Exception as e:
            raise NeatValueError(f"Failed to parse cardinality constraint: {data}") from e

    # If neither pattern matches, provide a clear error
    raise NeatValueError(
        f"Invalid restriction format: {data}. "
        f"Expected format: '{EntityTypes.value_constraint}:property(constraint,value)' "
        f"or '{EntityTypes.cardinality_constraint}:property(constraint,value[,on])'"
    )


T_ConceptRestriction = TypeVar("T_ConceptRestriction", bound=ConceptPropertyRestriction)

import logging
import os
from multiprocessing import get_context
from os import listdir
from typing import Any

import pandas as pd
import rdflib
from rdflib import Graph
from rdflib.plugins.sparql import prepareQuery

from config import Config
from src.lov_data_preparation import find_tags_from_list, find_comments_from_lists
from src.util import match_file_lod, CATEGORIES

logging.basicConfig(level=logging.INFO)
logger = logging.getLogger("dataset_preparation")

FORMATS = {'ttl', 'xml', 'nt', 'trig', 'n3', 'nquads'}


def log_query(query):
    logger.info(f"SPARQL Query: {query}")


def select_local_vocabularies(parsed_graph):
    Q_LOCAL_VOCABULARIES = prepareQuery("""
        SELECT DISTINCT ?predicate
        WHERE {
            ?subject ?predicate ?object .
            FILTER(STRSTARTS(STR(?predicate), "http://"))
            FILTER(!STRSTARTS(STR(STRBEFORE(STR(?predicate), "#")), "http://www.w3.org/"))
        }
        LIMIT 1000
    """)
    log_query(Q_LOCAL_VOCABULARIES)
    try:
        qres = parsed_graph.query(Q_LOCAL_VOCABULARIES)
    except Exception as e:
        logger.warning(f"SPARQL error in select_local_vocabularies: {e}")
        return set()

    vocabularies = set()
    for row in qres:
        predicate_uri = str(row.predicate)
        if not predicate_uri:
            continue

        if "#" in predicate_uri:
            vocabulary_uri = predicate_uri.split("#")[0]
        elif "/" in predicate_uri:
            parts = predicate_uri.rstrip("/").split("/")
            vocabulary_uri = "/".join(parts[:-1]) if len(parts) > 1 else predicate_uri
        else:
            vocabulary_uri = predicate_uri

        if not vocabulary_uri:
            continue

        vocabularies.add(vocabulary_uri)

    return vocabularies


def select_local_class(parsed_graph) -> list[str]:
    Q_LOCAL_CLASS = prepareQuery("""
        SELECT ?classUri (COUNT(?instance) AS ?instanceCount)
        WHERE {
            ?instance a ?classUri .
        }
        GROUP BY ?classUri
        ORDER BY DESC(?instanceCount)
        LIMIT 1000
    """)
    log_query(Q_LOCAL_CLASS)
    try:
        qres = parsed_graph.query(Q_LOCAL_CLASS)
    except Exception as e:
        logger.warning(f"SPARQL error in select_local_class: {e}")
        return []

    classes = set()
    for row in qres:
        class_uri = str(row.classUri)
        if class_uri:
            classes.add(class_uri)
    return list(classes)


def select_local_label(parsed_graph):
    ns = {
        "schema": 'http://schema.org',
        "skos": 'http://www.w3.org/2004/02/skos/core#',
        "rdfs": 'http://www.w3.org/2000/01/rdf-schema#',
        "foaf": 'http://xmlns.com/foaf/0.1/',
        "awol": 'http://bblfish.net/work/atom-owl/2006-06-06/#',
        "wdrs": 'http://www.w3.org/2007/05/powder-s#',
        "skosxl": 'http://www.w3.org/2008/05/skos-xl#'
    }

    Q_LOCAL_LABEL_EN = prepareQuery("""
        SELECT DISTINCT ?o
        WHERE {
            ?s a ?label .
            { ?s rdfs:label ?o }
            UNION
            { ?s foaf:name ?o }
            UNION
            { ?s skos:prefLabel ?o }
            UNION
            { ?s rdfs:comment ?o }
            UNION
            { ?s awol:label ?o }
            UNION
            { ?s skos:note ?o }
            UNION
            { ?s wdrs:text ?o }
            UNION
            { ?s skosxl:prefLabel ?o }
            UNION
            { ?s skosxl:literalForm ?o }
            UNION
            { ?s schema:name ?o }
            FILTER(langMatches(lang(?o), "en"))
        }
        LIMIT 1000
    """, initNs=ns)
    log_query(Q_LOCAL_LABEL_EN)

    try:
        qres = parsed_graph.query(Q_LOCAL_LABEL_EN)
    except Exception as e:
        logger.warning(f"SPARQL error in select_local_label (EN): {e}")
        qres = []

    if not qres or len(qres) < 2:
        Q_LOCAL_LABEL = prepareQuery("""
            SELECT DISTINCT ?o
            WHERE {
                ?s a ?label .
                { ?s rdfs:label ?o }
                UNION
                { ?s foaf:name ?o }
                UNION
                { ?s skos:prefLabel ?o }
                UNION
                { ?s rdfs:comment ?o }
                UNION
                { ?s awol:label ?o }
                UNION
                { ?s skos:note ?o }
                UNION
                { ?s wdrs:text ?o }
                UNION
                { ?s skosxl:prefLabel ?o }
                UNION
                { ?s skosxl:literalForm ?o }
                UNION
                { ?s schema:name ?o }
            }
            LIMIT 1000
        """, initNs=ns)
        log_query(Q_LOCAL_LABEL)
        try:
            qres = parsed_graph.query(Q_LOCAL_LABEL)
        except Exception as e:
            logger.warning(f"SPARQL error in select_local_label (fallback): {e}")
            return set()

    return {str(row.o) for row in qres}


def select_local_tld(parsed_graph):
    Q_LOCAL_TLD = prepareQuery("""
        SELECT DISTINCT ?o
        WHERE {
            ?s ?p ?o .
            FILTER(isIRI(?o))
        }
        LIMIT 1000
    """)
    log_query(Q_LOCAL_TLD)
    try:
        qres = parsed_graph.query(Q_LOCAL_TLD)
    except Exception as e:
        logger.warning(f"SPARQL error in select_local_tld: {e}")
        return set()

    tlds = set()
    for row in qres:
        url = str(row.o)
        if url.startswith(("http://", "https://")):
            try:
                host = url.split("/")[2]
                tld = host.split(".")[-1]
                if 1 < len(tld) <= 10:
                    tlds.add(tld)
            except Exception as exc:
                logger.warning(f"Unable to parse TLD from {url}: {exc}")
    return tlds


def select_local_property(parsed_graph):
    Q_LOCAL_PROPERTY = prepareQuery("""
        SELECT ?property (COUNT(?s) AS ?usageCount)
        WHERE {
            ?s ?property ?o .
            FILTER (?property != rdf:type)
        }
        GROUP BY ?property
        ORDER BY DESC(?usageCount)
        LIMIT 1000
    """, initNs={"rdf": rdflib.RDF})
    log_query(Q_LOCAL_PROPERTY)
    try:
        qres = parsed_graph.query(Q_LOCAL_PROPERTY)
    except Exception as e:
        logger.warning(f"SPARQL error in select_local_property: {e}")
        return []

    properties = set()
    for row in qres:
        property_uri = str(row.property)
        if not property_uri:
            continue
        properties.add(property_uri)
    return list(properties)


