from __future__ import annotations

import re

from ..rdflib import DefinedNamespace, Namespace, URIRef
from ..typing import Collection, Final, TypeAlias, Union
from .wikibase import WIKIBASE

T_NS: TypeAlias = Union[type[DefinedNamespace], Namespace]
T_URI: TypeAlias = Union[URIRef, str]


class Wikidata:
    """The Wikidata namespace."""

    WIKIDATA: Final[Namespace] = Namespace('http://www.wikidata.org/')
    P: Final[Namespace] = Namespace(WIKIDATA['prop/'])
    PQ: Final[Namespace] = Namespace(P['qualifier/'])
    PQN: Final[Namespace] = Namespace(PQ['value-normalized/'])
    PQV: Final[Namespace] = Namespace(PQ['value/'])
    PR: Final[Namespace] = Namespace(P['reference/'])
    PRN: Final[Namespace] = Namespace(PR['value-normalized/'])
    PRV: Final[Namespace] = Namespace(PR['value/'])
    PS: Final[Namespace] = Namespace(P['statement/'])
    PSN: Final[Namespace] = Namespace(PS['value-normalized/'])
    PSV: Final[Namespace] = Namespace(PS['value/'])
    WD: Final[Namespace] = Namespace(WIKIDATA['entity/'])
    WDATA: Final[Namespace] = Namespace(WIKIDATA['wiki/Special:EntityData/'])
    WDGENID: Final[Namespace] = Namespace(WIKIDATA['.well-known/genid/'])
    WDNO: Final[Namespace] = Namespace(P['novalue/'])
    WDREF: Final[Namespace] = Namespace(WIKIDATA['reference/'])
    WDS: Final[Namespace] = Namespace(WD['statement/'])
    WDT: Final[Namespace] = Namespace(P['direct/'])
    WDV: Final[Namespace] = Namespace(WIKIDATA['value/'])

    namespaces: Final[dict[str, Namespace]] = {
        str(WIKIDATA): WIKIDATA,
        str(P): P,
        str(PQ): PQ,
        str(PQN): PQN,
        str(PQV): PQV,
        str(PR): PR,
        str(PRN): PRN,
        str(PRV): PRV,
        str(PS): PS,
        str(PSN): PSN,
        str(PSV): PSV,
        str(WD): WD,
        str(WDATA): WDATA,
        str(WDGENID): WDGENID,
        str(WDNO): WDNO,
        str(WDREF): WDREF,
        str(WDS): WDS,
        str(WDT): WDT,
        str(WDV): WDV,
    }

    schema: Final[dict[str, Namespace]] = {
        'p': P,
        'pq': PQ,
        'pqv': PQV,
        'pr': PR,
        'prv': PRV,
        'ps': PS,
        'psv': PSV,
        'wdno': WDNO,
        'wdt': WDT,
    }

    prefixes: Final[dict[str, Namespace]] = {
        'wikidata': WIKIDATA,
        'p': P,
        'pq': PQ,
        'pqn': PQN,
        'pqv': PQV,
        'pr': PR,
        'prn': PRN,
        'prv': PRV,
        'ps': PS,
        'psn': PSN,
        'psv': PSV,
        'wd': WD,
        'wdata': WDATA,
        'wdgenid': WDGENID,
        'wdno': WDNO,
        'wdref': WDREF,
        'wds': WDS,
        'wdt': WDT,
        'wdv': WDV,
    }

    default_entity_prefixes: Final[Collection[T_NS]] = (WD,)
    default_item_prefixes: Final[Collection[T_NS]] = (WD,)
    default_property_prefixes: Final[Collection[T_NS]] = (WD,)
    default_lexeme_prefixes: Final[Collection[T_NS]] = (WD,)
    default_some_value_prefixes: Final[Collection[T_NS]] = (WDGENID,)

    PREFERRED: Final[URIRef] = WIKIBASE.PreferredRank
    NORMAL: Final[URIRef] = WIKIBASE.NormalRank
    DEPRECATED: Final[URIRef] = WIKIBASE.DeprecatedRank

    @classmethod
    def is_wikidata_uri(cls, uri: T_URI) -> bool:
        return uri.startswith(cls.WIKIDATA)

    @classmethod
    def split_wikidata_uri(
            cls,
            uri: T_URI,
            _re=re.compile(r'^(.*/)([^/]*)$')
    ) -> tuple[T_NS, str]:
        if cls.is_wikidata_uri(uri):
            m = _re.match(uri)
            assert m is not None
            pfx, name = m.groups()
            return cls.namespaces[pfx], name
        else:
            raise ValueError(f'bad Wikidata URI: {uri}')

    @classmethod
    def get_wikidata_namespace(cls, uri: T_URI) -> T_NS:
        return cls.split_wikidata_uri(uri)[0]

    @classmethod
    def get_wikidata_name(cls, uri: T_URI) -> str:
        return cls.split_wikidata_uri(uri)[1]

    @classmethod
    def is_wd_entity(
            cls,
            uri: T_URI,
            prefixes: Collection[T_NS] = default_entity_prefixes
    ) -> bool:
        try:
            pfx, name = cls.split_wikidata_uri(uri)
        except ValueError:
            return False
        else:
            return cls._is_wd_entity(pfx, name, prefixes)

    @classmethod
    def _is_wd_entity(
            cls,
            prefix: T_NS,
            name: str,
            prefixes: Collection[T_NS]
    ) -> bool:
        return prefix in prefixes and name[0] in 'QPL'

    @classmethod
    def is_wd_item(
            cls,
            uri: T_URI,
            prefixes: Collection[T_NS] = default_item_prefixes
    ) -> bool:
        try:
            pfx, name = cls.split_wikidata_uri(uri)
        except ValueError:
            return False
        else:
            return cls._is_wd_item(pfx, name, prefixes)

    @classmethod
    def _is_wd_item(
            cls,
            prefix: T_NS,
            name: str,
            prefixes: Collection[T_NS]
    ) -> bool:
        return prefix in prefixes and name[0] == 'Q'

    @classmethod
    def is_wd_property(
            cls,
            uri: T_URI,
            prefixes: Collection[T_NS] = default_property_prefixes
    ) -> bool:
        try:
            pfx, name = cls.split_wikidata_uri(uri)
        except ValueError:
            return False
        else:
            return cls._is_wd_property(pfx, name, prefixes)

    @classmethod
    def _is_wd_property(
            cls,
            prefix: T_NS,
            name: str,
            prefixes: Collection[T_NS]
    ) -> bool:
        return prefix in prefixes and name[0] == 'P'

    @classmethod
    def is_wd_lexeme(
            cls,
            uri: T_URI,
            prefixes: Collection[T_NS] = default_lexeme_prefixes
    ) -> bool:
        try:
            pfx, name = cls.split_wikidata_uri(uri)
        except ValueError:
            return False
        else:
            return cls._is_wd_lexeme(pfx, name, prefixes)

    @classmethod
    def _is_wd_lexeme(
            cls,
            prefix: T_NS,
            name: str,
            prefixes: Collection[T_NS]
    ) -> bool:
        return prefix in prefixes and name[0] == 'L'

    @classmethod
    def is_wd_some_value(
            cls,
            uri: T_URI,
            prefixes: Collection[T_NS] = default_some_value_prefixes
    ) -> bool:
        try:
            pfx, name = cls.split_wikidata_uri(uri)
        except ValueError:
            return False
        else:
            return cls._is_wd_some_value(pfx, name, prefixes)

    @classmethod
    def _is_wd_some_value(
            cls,
            prefix: T_NS,
            name: str,
            prefixes: Collection[T_NS]
    ) -> bool:
        return prefix in prefixes

    @classmethod
    def is_wikibase_preferred_rank(cls, uri: T_URI) -> bool:
        return str(uri) == str(cls.PREFERRED)

    @classmethod
    def is_wikibase_normal_rank(cls, uri: T_URI) -> bool:
        return str(uri) == str(cls.NORMAL)

    @classmethod
    def is_wikibase_deprecated_rank(cls, uri: T_URI) -> bool:
        return str(uri) == str(cls.DEPRECATED)

@click.command()
@click.option("-i", "--graph", type=click.Path(), required=True)
@click.option("--kgcl-file", type=click.File("r"))
@click.option("--output", "-o", type=click.File(mode="wb"), default=sys.stdout)
@click.option("-v", "--verbose", count=True)
@click.argument("patch")
def cli(patch, verbose: int, graph, kgcl_file, output):
    """
    Modify graph based on KGCL commands.
    """
    if verbose >= 2:
        logging.basicConfig(level=logging.DEBUG)
    elif verbose == 1:
        logging.basicConfig(level=logging.INFO)
    else:
        logging.basicConfig(level=logging.WARNING)
    # read kgcl commands from file
    if kgcl_file:
        kgcl_patch = kgcl_file.read()
    elif patch:
        kgcl_patch = patch
    else:
        raise ValueError(f"Must pass EITHER kgcl-file OR kgcl")

    # parser kgcl commands
    parsed_patch = parser.parse(kgcl_patch)
    logging.info(f"Patch: {patch}")

    # apply kgcl commands as SPARQL UPDATE queries to graph
    g = rdflib.Graph()
    # g.load(graph, format=guess_format(graph))
    g.parse(
        graph, format=guess_format(graph)
    )  # , format="nt") #TODO: this doesn't always work
    graph_transformer.apply_patch(parsed_patch, g)

    # save updated graph
    g.serialize(destination=output, format="ttl")

def manchesterSyntax(thing, store, boolean=None, transientList=False):
    """
    Core serialization
    """
    assert thing is not None
    if boolean:
        if transientList:
            liveChildren = iter(thing)
            children = [manchesterSyntax(child, store) for child in thing]
        else:
            liveChildren = iter(Collection(store, thing))
            children = [manchesterSyntax(
                child, store) for child in Collection(store, thing)]
        if boolean == OWL_NS.intersectionOf:
            childList = []
            named = []
            for child in liveChildren:
                if isinstance(child, URIRef):
                    named.append(child)
                else:
                    childList.append(child)
            if named:
                def castToQName(x):
                    prefix, uri, localName = store.compute_qname(x)
                    return ':'.join([prefix, localName])

                if len(named) > 1:
                    prefix = u'( ' + u' AND '.join(map(
                        castToQName, named)) + u' )'
                else:
                    prefix = manchesterSyntax(named[0], store)
                if childList:
                    return str(prefix) + u' THAT ' + u' AND '.join(
                        [str(manchesterSyntax(x, store)) for x in childList])
                else:
                    return prefix
            else:
                return u'( ' + u' AND '.join(
                    [str(c) for c in children]) + u' )'
        elif boolean == OWL_NS.unionOf:
            return u'( ' + u' OR '.join([str(c) for c in children]) + ' )'
        elif boolean == OWL_NS.oneOf:
            return u'{ ' + u' '.join([str(c) for c in children]) + ' }'
        else:
            assert boolean == OWL_NS.complementOf
    elif OWL_NS.Restriction in store.objects(
            subject=thing, predicate=RDF.type):
        prop = list(
            store.objects(subject=thing, predicate=OWL_NS.onProperty))[0]
        prefix, uri, localName = store.compute_qname(prop)
        propString = u':'.join([prefix, localName])
        label = first(store.objects(subject=prop, predicate=RDFS.label))
        if label:
            propString = "'%s'" % label
        for onlyClass in store.objects(
                subject=thing, predicate=OWL_NS.allValuesFrom):
            return u'( %s ONLY %s )' % (
                propString, manchesterSyntax(onlyClass, store))
        for val in store.objects(subject=thing, predicate=OWL_NS.hasValue):
            return u'( %s VALUE %s )' % (
                propString,
                manchesterSyntax(val.encode('utf-8', 'ignore'), store))
        for someClass in store.objects(
                subject=thing, predicate=OWL_NS.someValuesFrom):
            return u'( %s SOME %s )' % (
                propString, manchesterSyntax(someClass, store))
        cardLookup = {OWL_NS.maxCardinality: 'MAX',
                      OWL_NS.minCardinality: 'MIN',
                      OWL_NS.cardinality: 'EQUALS'}
        for s, p, o in store.triples_choices(
                (thing, list(cardLookup.keys()), None)):
            return u'( %s %s %s )' % (
                propString, cardLookup[p], o.encode('utf-8', 'ignore'))
    compl = list(store.objects(subject=thing, predicate=OWL_NS.complementOf))
    if compl:
        return '( NOT %s )' % (manchesterSyntax(compl[0], store))
    else:
        prolog = '\n'.join(
            ["PREFIX %s: <%s>" % (k, nsBinds[k]) for k in nsBinds])
        qstr = \
            prolog + \
            "\nSELECT ?p ?bool WHERE {?class a owl:Class; ?p ?bool ." + \
            "?bool rdf:first ?foo }"
        initb = {Variable("?class"): thing}
        for boolProp, col in \
                store.query(qstr, processor="sparql", initBindings=initb):
            if not isinstance(thing, URIRef):
                return manchesterSyntax(col, store, boolean=boolProp)
        try:
            prefix, uri, localName = store.compute_qname(thing)
            qname = u':'.join([prefix, localName])
        except Exception:
            if isinstance(thing, BNode):
                return thing.n3()
            return u"<" + thing + ">"
            logger.debug(list(store.objects(subject=thing, predicate=RDF.type)))
            raise
            return '[]'  # +thing._id.encode('utf-8')+'</em>'
        label = first(Class(thing, graph=store).label)
        if label:
            return label.encode('utf-8', 'ignore')
        else:
            return qname.encode('utf-8', 'ignore')

def GetIdentifiedClasses(graph):
    for c in graph.subjects(predicate=RDF.type, object=OWL_NS.Class):
        if isinstance(c, URIRef):
            yield Class(c)

def _set_type(self, kind):
    if not kind:
        return
    if isinstance(kind, (Individual, Identifier)):
        self.graph.add(
            (self.identifier, RDF.type, classOrIdentifier(kind)))
    else:
        for c in kind:
            assert isinstance(c, (Individual, Identifier))
            self.graph.add(
                (self.identifier, RDF.type, classOrIdentifier(c)))

def _set_identifier(self, i):
    assert i
    if i != self.__identifier:
        oldStmtsOut = [(p, o) for s, p, o in self.graph.triples(
            (self.__identifier, None, None))]
        oldStmtsIn = [(s, p) for s, p, o in self.graph.triples(
            (None, None, self.__identifier))]
        for p1, o1 in oldStmtsOut:
            self.graph.remove((self.__identifier, p1, o1))
        for s1, p1 in oldStmtsIn:
            self.graph.remove((s1, p1, self.__identifier))
        self.__identifier = i
        self.graph.addN(
            [(i, p1, o1, self.graph) for p1, o1 in oldStmtsOut])
        self.graph.addN([(s1, p1, i, self.graph) for s1, p1 in oldStmtsIn])
    if not isinstance(i, BNode):
        try:
            prefix, uri, localName = self.graph.compute_qname(i)
            self.qname = u':'.join([prefix, localName])
        except:
            pass

def _set_sameAs(self, term):
    # if not kind:
    #     return
    if isinstance(term, (Individual, Identifier)):
        self.graph.add(
            (self.identifier, OWL_NS.sameAs, classOrIdentifier(term)))
    else:
        for c in term:
            assert isinstance(c, (Individual, Identifier))
            self.graph.add(
                (self.identifier, OWL_NS.sameAs, classOrIdentifier(c)))

def _set_comment(self, comment):
    if not comment:
